package com.lingualearn.app.data.content

/**
 * Russian (ru) and Mandarin Chinese (zh) comprehensive curriculum content.
 * 10 levels × 6 topics = 60 distinct lessons per language.
 */
object RussianCurriculum {
    fun getContent(level: Int, topic: String): CurriculumLessonContent {
        return when (level) {
            1 -> when (topic) {
                "Greetings" -> CurriculumLessonContent("Здравствуйте! / Привет!", "Hello (formal) / Hi (informal)", "ZDRAHST-vuy-tyeh / pree-VYET", "Здравствуйте! Как ваши дела?", "Hello! How are you? (formal)", "'Здравствуйте' has a silent first 'v' (pronounced zdravstvuyte).")
                "Introducing Yourself" -> CurriculumLessonContent("Меня зовут Анна", "My name is Anna", "mee-NYAH zah-VOOT AHN-nah", "Меня зовут Анна, я из Москвы.", "My name is Anna, I am from Moscow.", "Literally 'They call me Anna' (genitive pronoun 'menya').")
                "Yes / No / Basic Responses" -> CurriculumLessonContent("Да / Нет / Пожалуйста / Спасибо", "Yes / No / Please / Thank you", "dah / nyet / pah-ZHAH-loo-stah / spah-SEE-bah", "Да, пожалуйста! Большое спасибо за помощь.", "Yes, please! Many thanks for the help.", "'Пожалуйста' also means 'you're welcome'.")
                "Numbers 1–10" -> CurriculumLessonContent("Один, два, три, четыре, пять...", "1 to 10 numerals", "ah-DEEN, dvah, tree, cheh-TY-reh, pyaht", "Два билета на поезд, пожалуйста.", "Two tickets for the train, please.", "Russian numerals change forms depending on the grammatical case.")
                "Basic Pronouns" -> CurriculumLessonContent("Я, ты, он, она, мы, вы, они", "I, you (inf), he, she, we, you (formal), they", "yah, ty, ohn, ah-NAH, my, vy, ah-NEE", "Мы вместе изучаем русский язык.", "We are studying the Russian language together.", "Use 'Вы' with a capital for formal address to one person.")
                else -> CurriculumLessonContent("Извините и До свидания", "Excuse me / Sorry and Goodbye", "eez-vee-NEE-tyeh / dah svee-DAH-nee-yah", "Извините, где находится станция метро?", "Excuse me, where is the subway station located?", "'До свидания' literally means 'until meeting again'.")
            }
            2 -> when (topic) {
                "Family" -> CurriculumLessonContent("Семья (мать, отец, брат, сестра)", "Family (mother, father, brother, sister)", "seem-YAH", "Мой брат и моя сестра живут в Петербурге.", "My brother and my sister live in St. Petersburg.", "Possessives agree with gender: 'мой брат' (m), 'моя сестра' (f).")
                "Colors" -> CurriculumLessonContent("Красный, синий, жёлтый, зелёный", "Red, Blue, Yellow, Green", "KRAHS-ny, SEE-nee, ZHYOL-ty, zyeh-LYOH-ny", "Красная площадь — сердце Москвы.", "Red Square is the heart of Moscow.", "In old Russian, 'красный' originally meant beautiful.")
                "Food" -> CurriculumLessonContent("Борщ, пирожки и горячий чай", "Borscht, pirozhki, and hot tea", "borshch, pee-rahzh-KEE, chye", "Горячий борщ со сметаной очень вкусный.", "Hot borscht with sour cream is very delicious.", "Drinking hot black tea with lemon is a cornerstone of hospitality.")
                "Days & Months" -> CurriculumLessonContent("С понедельника по воскресенье", "From Monday to Sunday", "pah-nee-DYEL-neek dah vahs-kree-SYEN-yeh", "В субботу вечером мы идём в Большой театр.", "On Saturday evening we are going to the Bolshoi Theatre.", "Use 'в' + accusative for days of the week: 'в субботу'.")
                "Simple Questions" -> CurriculumLessonContent("Кто? Что? Где? Когда? Почему?", "Who? What? Where? When? Why?", "ktoh, shtoh, gdeh, kahg-DAH, pah-cheh-MOO", "Где находится исторический музей?", "Where is the history museum located?", "Notice 'что' (what) is pronounced with 'sh' (shto).")
                else -> CurriculumLessonContent("Есть, пить, идти, ехать", "Eat, drink, walk, go by transport", "yest, peet, eed-TEE, YEH-khat", "Мы идём пешком, а они едут на автобусе.", "We are going on foot, while they are going by bus.", "Russian makes a strict distinction between walking (идти) and riding (ехать).")
            }
            3 -> when (topic) {
                "Daily Routine" -> CurriculumLessonContent("Вставать рано и пить кофе", "Waking up early and drinking coffee", "vstah-VAHT RAH-nah", "Я встаю в семь утра и делаю зарядку.", "I wake up at seven AM and do morning exercises.", "Reflexive verbs end in '-ся' or '-сь'.")
                "Shopping" -> CurriculumLessonContent("Сколько это стоит?", "How much does this cost?", "SKOHL-kah EH-tah STOH-eet", "Скажите, пожалуйста, сколько стоит этот сувенир?", "Tell me, please, how much does this souvenir cost?", "Essential phrase for market stalls and bookshops.")
                "Time" -> CurriculumLessonContent("Который сейчас час?", "What time is it right now?", "kah-TOH-ry say-CHAHS chahs", "Сейчас два часа дня.", "It is two o'clock in the afternoon right now.", "Use 'час' for 1, 'часа' for 2-4, 'часов' for 5-20.")
                "Directions" -> CurriculumLessonContent("Идите прямо и поверните направо", "Go straight and turn right", "ee-DEE-tyeh PRYAH-mah", "Идите прямо два квартала, затем налево.", "Go straight for two blocks, then turn left.", "'Направо' is to the right, 'налево' is to the left.")
                "Simple Sentences" -> CurriculumLessonContent("Я хочу прочитать эту книгу", "I want to read this book", "yah khah-CHOO", "Я хочу заказать столик в уютном кафе.", "I want to reserve a table in a cozy café.", "Pair 'я хочу' directly with an infinitive verb.")
                else -> CurriculumLessonContent("Как поживаете? Всё хорошо?", "How are you doing? Everything good?", "kahk pah-zhee-VAH-yeh-tyeh", "Спасибо, всё в порядке, работаем потихоньку.", "Thanks, everything is fine, slowly doing our work.", "Classic everyday Russian reply.")
            }
            4 -> when (topic) {
                "Past Events" -> CurriculumLessonContent("Вчера я посетил Эрмитаж", "Yesterday I visited the Hermitage", "vcheh-RAH yah pah-seh-TEEL", "Вчера мы целый день любовались картинами.", "Yesterday we spent the whole day admiring the paintings.", "Past tense inflects for gender: -л (m), -ла (f), -ло (n), -ли (pl).")
                "Future Plans" -> CurriculumLessonContent("Я поеду на Байкал следующим летом", "I will travel to Lake Baikal next summer", "yah pah-YEH-doo", "В следующем году я буду учиться в университете.", "Next year I will be studying at the university.", "Imperfective future uses 'буду' + infinitive.")
                "Travel" -> CurriculumLessonContent("Поезд Сапсан и вокзал", "Sapsan high-speed train and station", "POH-yezd sahp-SAHN", "Скоростной поезд Сапсан отправляется в полдень.", "The high-speed Sapsan train departs at noon.", "Sapsan connects Moscow and Saint Petersburg in four hours.")
                "Restaurants" -> CurriculumLessonContent("Принесите счёт, пожалуйста", "Please bring the bill", "pree-nee-SEE-tyeh shchyot", "Всё было превосходно, принесите счёт, пожалуйста.", "Everything was superb, please bring the bill.", "Pronounce 'счёт' as 'shchyot'.")
                "Describing People" -> CurriculumLessonContent("Добрый, умный и надёжный человек", "Kind, smart, and reliable person", "DOHB-ry, OOM-ny, nah-DYOHZH-ny", "Мой друг очень надёжный и верный товарищ.", "My friend is a very reliable and loyal companion.", "Adjectives in Russian agree in gender, number, and case.")
                else -> CurriculumLessonContent("Прекрасная солнечная погода", "Wonderful sunny weather", "pree-KRAHS-nah-yah pah-GOH-dah", "После долгой зимы наконец наступили тёплые дни.", "After the long winter, warm days have finally arrived.", "Spring and summer sun is joyously celebrated across Russia.")
            }
            5 -> when (topic) {
                "Longer Conversations" -> CurriculumLessonContent("Позвольте высказать своё мнение", "Allow me to express my opinion", "pahz-VOHL-tyeh VYS-kah-zaht", "Позвольте добавить важное замечание к обсуждению.", "Allow me to add an important remark to the discussion.", "Polite formal conversational formula.")
                "Opinions" -> CurriculumLessonContent("По моему мнению", "In my opinion", "pah mah-yeh-MOO MNYEH-nee-yoo", "По моему мнению, чтение развивает кругозор.", "In my opinion, reading broadens one's horizons.", "'По моему мнению' introduces evaluated perspectives.")
                "Experiences" -> CurriculumLessonContent("Незабываемое путешествие по тайге", "An unforgettable journey across the taiga", "nee-zah-by-VAH-yeh-mah-yeh", "Поездка по Транссибирской магистрали оставила глубокий след.", "The trip on the Trans-Siberian railway left a profound impression.", "Sharing travel reflections.")
                "Comparisons" -> CurriculumLessonContent("Гораздо интереснее, чем...", "Much more interesting than...", "gah-RAHZ-dah een-tyeh-RYES-nee-yeh", "Этот роман гораздо глубже, чем экранизация.", "This novel is far deeper than the film adaptation.", "Use 'чем' with comparatives followed by nominative case.")
                "More Complex Grammar" -> CurriculumLessonContent("Условное наклонение с частицей Бы", "Conditional mood with the particle By", "oo-SLOHV-nah-yeh", "Если бы у меня было время, я бы путешествовал больше.", "If I had time, I would travel more.", "Subjunctive simply adds 'бы' to the past tense.")
                else -> CurriculumLessonContent("Аудирование на русском языке", "Russian listening comprehension", "ow-dee-ROH-vah-nee-yeh", "Я слушаю радиопередачи для улучшения восприятия речи.", "I listen to radio broadcasts to enhance speech perception.", "Pay close attention to mobile stress and vowel reduction (akanye).")
            }
            6 -> when (topic) {
                "Storytelling" -> CurriculumLessonContent("В некотором царстве, в некотором государстве...", "In a certain kingdom, in a certain realm...", "v NYEH-kah-tah-rahm TSARST-vyeh", "Сказка — ложь, да в ней намёк, добрым молодцам урок.", "A fairy tale is fiction, but there is a hint in it, a lesson.", "The iconic formula ending traditional Russian skazki.")
                "Workplace Conversations" -> CurriculumLessonContent("Деловое совещание и отчётность", "Business meeting and reporting", "dee-lah-VOH-yeh sah-vyeh-SHCHAH-nee-yeh", "Мы обсудили стратегические планы на следующий квартал.", "We discussed strategic plans for the next quarter.", "Professional Russian is precise, structured, and polite.")
                "Social Situations" -> CurriculumLessonContent("Спасибо за радушное гостеприимство", "Thank you for the warm hospitality", "gahs-tee-pree-EEMST-vah", "Мы бесконечно благодарны вам за теплоту и радушие.", "We are endlessly grateful to you for your warmth and cordiality.", "Hospitality ('гостеприимство') is a sacred traditional virtue.")
                "News & Media" -> CurriculumLessonContent("Главные заголовки прессы", "Main headlines of the press", "GLAHV-ny-yeh zah-gah-LOHV-kee", "Аналитическая статья рассматривает развитие науки.", "The analytical article examines the development of science.", "Journalistic Russian employs rich participial clauses.")
                "Idiomatic Expressions" -> CurriculumLessonContent("Семь пятниц на неделе", "Seven Fridays in a week (unreliable/indecisive)", "syem PYAT-neets", "С ним трудно работать, у него семь пятниц на неделе.", "It's hard to work with him; he changes his mind constantly.", "Beloved Russian idiom describing indecisiveness.")
                else -> CurriculumLessonContent("Виды глаголов: совершенный и несовершенный", "Aspects of verbs: Perfective and Imperfective", "VEED-y glah-GOH-lahv", "Я читал роман (процесс) и прочитал его до конца (результат).", "I was reading the novel (process) and finished it (result).", "Aspect is central to Russian verbal morphology.")
            }
            7 -> when (topic) {
                "Complex Conversations" -> CurriculumLessonContent("Социальные тенденции и демография", "Social trends and demographics", "sah-tsye-AHL-ny-yeh tyen-DYEN-tsee", "Необходимо тщательно изучить долгосрочные последствия.", "It is necessary to meticulously examine long-term consequences.", "Debating complex societal themes.")
                "Debate & Opinions" -> CurriculumLessonContent("Я категорически не согласен", "I categorically disagree", "kah-tyeh-gah-REE-chehs-kee", "При всём уважении, факты опровергают эту точку зрения.", "With all due respect, the facts refute this point of view.", "Firm but cultured argumentation.")
                "Abstract Topics" -> CurriculumLessonContent("Философия 'русской души' и духовность", "The concept of the 'Russian soul' and spirituality", "ROOS-skoy doo-SHEE", "Широта души, сострадание и стремление к высшей правде.", "Breadth of soul, compassion, and the pursuit of higher truth.", "Explored across classic Russian philosophy and literature.")
                "Natural Expressions" -> CurriculumLessonContent("Зарубить себе на носу / Не лыком шит", "Carve into your nose (remember well) / Not born yesterday", "zah-roo-BEET seh-BYEH", "Заруби себе на носу: честность превыше всего.", "Remember this well: honesty is above all else.", "Colorful ancient Russian idioms.")
                "Listening Comprehension" -> CurriculumLessonContent("Понимание университетских лекций", "Comprehending university keynote lectures", "ahn-tseh-PLYEN-tsee-yah", "Слушатели внимательно следили за ходом научной дискуссии.", "Listeners attentively followed the course of the scientific debate.", "Following high-register academic spoken Russian.")
                else -> CurriculumLessonContent("Научно-публицистическое эссе", "Scholarly and publicist essay writing", "nah-OOCH-nah poo-blee-TSEES-teek", "Глубокий анализ темы с привлечением авторитетных источников.", "In-depth analysis of the topic drawing on authoritative sources.", "Scholarly Russian composition.")
            }
            8 -> when (topic) {
                "Advanced Conversations" -> CurriculumLessonContent("Стратегическое управление и анализ рисков", "Strategic management and risk analysis", "strah-tyeh-GEE-chehs-kah-yeh", "Принятие решений требует взвешенной оценки всех рисков.", "Decision-making requires balanced evaluation of all risks.", "Executive corporate and governmental vocabulary.")
                "Cultural Context" -> CurriculumLessonContent("Золотой и Серебряный век литературы", "The Golden and Silver Ages of literature", "zah-lah-TOY vek", "Пушкин, Толстой и Достоевский обогатили мировую культуру.", "Pushkin, Tolstoy, and Dostoevsky enriched world culture.", "Literature is celebrated as Russia's greatest spiritual contribution.")
                "Nuanced Vocabulary" -> CurriculumLessonContent("Эфемерный, многогранный и монументальный", "Ephemeral, multifaceted, and monumental", "eh-feh-MYER-ny / mnah-gah-GRAHN-ny", "Его научный труд представляет собой монументальное исследование.", "His scholarly work constitutes a monumental research study.", "High-register literary adjectives.")
                "Advanced Listening" -> CurriculumLessonContent("Нюансы интонации и скрытый подтекст", "Intonation nuances and hidden subtext", "een-tah-NAH-tsee-yah", "Умение улавливать тонкую иронию и недосказанность в речи.", "Ability to catch subtle irony and unsaid subtext in spoken dialogue.", "Russian intonation contours (IK-1 through IK-7) signal nuance.")
                "Formal vs Informal Speech" -> CurriculumLessonContent("Канцелярит и живая разговорная речь", "Bureaucratic legalese vs Living spoken speech", "kahn-tseh-lyah-REET", "Умелое разграничение официально-делового стиля и непринуждённого общения.", "Skilled demarcation between formal bureaucratic and casual styles.", "Mastering social registers.")
                else -> CurriculumLessonContent("Деепричастные и причастные обороты", "Adverbial and participial clauses", "dyeh-yeh-pree-CHAHST-ny-yeh", "Завершив доклад, докладчик ответил на многочисленные вопросы.", "Having completed the report, the speaker fielded numerous queries.", "Participles elevate written Russian to literary stature.")
            }
            9 -> when (topic) {
                "Professional Communication" -> CurriculumLessonContent("Дипломатический протокол и соглашения", "Diplomatic protocol and covenants", "dee-plah-mah-TEE-chehs-kee", "Стороны ратифицировали многосторонний пакт о сотрудничестве.", "The parties ratified the multilateral cooperation pact.", "High ministerial and diplomatic Russian.")
                "Advanced Reading" -> CurriculumLessonContent("Лев Толстой: 'Война и мир'", "Leo Tolstoy: 'War and Peace'", "lyef tahl-STOY", "Анализ философских отступлений и психологизма персонажей.", "Analyzing philosophical digressions and character psychologies.", "Reading epic masterpieces in the unabridged original.")
                "Idioms & Expressions" -> CurriculumLessonContent("Пройти сквозь огонь, воду и медные трубы", "Endure fire, water, and brass pipes (ultimate trials)", "prah-EE-tee skvohz ah-GOHN", "Он прошёл огонь и воду, заслужив непоколебимый авторитет.", "He went through fire and water, earning unshakeable authority.", "Surviving life's toughest ordeals.")
                "Advanced Writing" -> CurriculumLessonContent("Академическая монография и рецензия", "Academic monograph and scholarly review", "mah-nah-GRAH-fee-yah", "Публикация рецензируемой статьи в ведущем научном журнале.", "Publishing a peer-reviewed paper in a leading scientific journal.", "Publishable scholarly prose.")
                "Difficult Listening" -> CurriculumLessonContent("Синхронный перевод и быстрые дебаты", "Simultaneous interpretation and rapid debate", "seen-KHROHN-ny", "Точное восприятие сложнейшей аргументации в режиме реального времени.", "Accurate perception of intricate argumentation in real time.", "Supreme auditory discernment.")
                else -> CurriculumLessonContent("Владение языком на уровне носителя", "Near-native mastery of language", "vlah-DYEH-nee-yeh", "Способность тонко и остроумно излагать сложнейшие мысли.", "Ability to subtly and wittily articulate complex thoughts.", "Flawless bilingual execution.")
            }
            else -> when (topic) {
                "Natural Conversation" -> CurriculumLessonContent("Абсолютная непринуждённость и живость речи", "Absolute ease and natural liveliness", "zhee-VAHST", "Беседа течёт легко, остроумно и совершенно естественно.", "The conversation flows effortlessly, wittily, and completely naturally.", "Native cadence and rhythm.")
                "Humor & Cultural References" -> CurriculumLessonContent("Интеллектуальный юмор и крылатые фразы", "Intellectual humor and winged idioms from cinema", "kryl-LAH-ty-yeh FRAH-zy", "Понимание цитат из советской киноклассики и тонких анекдотов.", "Understanding quotes from Soviet cinema classics and subtle parables.", "Cultural humor requires deep cinematic awareness.")
                "Advanced Debates" -> CurriculumLessonContent("Ораторское мастерство и полемика", "Oratorical mastery and polemics", "ah-RAH-tahr-skah-yeh", "Убедительное ведение полемики с неотразимой риторической силой.", "Persuasively conducting debate with irresistible rhetorical force.", "Commanding public oratory.")
                "Professional Fluency" -> CurriculumLessonContent("Лидерство на международной арене", "Leadership on the international stage", "LEE-dyer-stvah", "Председательство на международных саммитах на русском языке.", "Chairing international summits in the Russian language with distinction.", "Executive diplomatic fluency.")
                "Native-Speed Listening" -> CurriculumLessonContent("Мгновенная слуховая расшифровка", "Instantaneous auditory decoding", "sluh-khah-VAH-yah", "Улавливание всех аллюзий, диалектизмов и быстрого сленга.", "Catching all allusions, dialectal twists, and rapid colloquialisms.", "Total acoustic mastery.")
                else -> CurriculumLessonContent("Полное культурно-языковое слияние", "Complete cultural and linguistic synthesis", "slee-YAH-nee-yeh", "Глубокое сопереживание и жизнь в стихии русского слова.", "Deep empathy and living within the elemental spirit of the Russian word.", "Total cultural and linguistic harmony.")
            }
        }
    }
}

object MandarinCurriculum {
    fun getContent(level: Int, topic: String): CurriculumLessonContent {
        return when (level) {
            1 -> when (topic) {
                "Greetings" -> CurriculumLessonContent("你好！ / 早上好", "Hello! / Good morning", "Nǐ hǎo! / Zǎoshang hǎo", "你好！很高兴认识你。", "Hello! Nice to meet you.", "Use 'Nín hǎo' (您好) as a polite mark of respect for elders.")
                "Introducing Yourself" -> CurriculumLessonContent("我叫李明，我是学生", "My name is Li Ming, I am a student", "Wǒ jiào Lǐ Míng, wǒ shì xuésheng", "我叫李明，我来自中国北京。", "My name is Li Ming, I come from Beijing, China.", "'Wǒ jiào' (I am called) is the standard self-introduction.")
                "Yes / No / Basic Responses" -> CurriculumLessonContent("是 / 不是 / 请 / 谢谢", "Yes / No / Please / Thank you", "Shì / Bú shì / Qǐng / Xièxie", "是的，请帮我一下。非常感谢！", "Yes, please help me. Thank you very much!", "Reply to 'Xièxie' with 'Bú kèqi' (You're welcome).")
                "Numbers 1–10" -> CurriculumLessonContent("一、二、三、四、五...", "1 to 10 numerals", "Yī, èr, sān, sì, wǔ", "请给我两杯绿茶。", "Please give me two cups of green tea.", "Use 'liǎng' (两) instead of 'èr' when counting items before measure words.")
                "Basic Pronouns" -> CurriculumLessonContent("我、你、他、她、我们", "I, you, he, she, we", "Wǒ, nǐ, tā, tā, wǒmen", "我们一起努力学习普通话。", "We are working hard to learn Mandarin together.", "Plural is formed by simply adding 'men' (们) to pronouns.")
                else -> CurriculumLessonContent("对不起 与 再见", "Sorry / Excuse me and Goodbye", "Duìbuqǐ yǔ Zàijiàn", "对不起，请问地铁站在哪里？", "Excuse me, may I ask where the subway station is located?", "'Zàijiàn' literally means 'see you again'.")
            }
            2 -> when (topic) {
                "Family" -> CurriculumLessonContent("家庭（爸爸、妈妈、哥哥、妹妹）", "Family (father, mother, older brother, younger sister)", "Jiātíng", "我哥哥在上海工作，我妹妹上大学。", "My older brother works in Shanghai and my younger sister attends university.", "Chinese uses distinct precise terms for every specific relative.")
                "Colors" -> CurriculumLessonContent("红、蓝、黄、绿、白", "Red, Blue, Yellow, Green, White", "Hóng, lán, huáng, lǜ, bái", "在中国文化中，红色象征吉祥和喜庆。", "In Chinese culture, red symbolizes good fortune and celebration.", "Red is the auspicious color worn during weddings and Chinese New Year.")
                "Food" -> CurriculumLessonContent("饺子、米饭、面条与中国茶", "Dumplings, rice, noodles, and Chinese tea", "Jiǎozi, mǐfàn, miàntiáo", "热腾腾的水饺是春节必不可少的美食。", "Steaming hot dumplings are an essential delicacy during Spring Festival.", "Tea culture in China dates back thousands of years.")
                "Days & Months" -> CurriculumLessonContent("星期一到星期日", "Monday to Sunday", "Xīngqīyī dào xīngqīrì", "这个星期六晚上我们一起吃火锅吧。", "Let's eat hotpot together this Saturday evening.", "Days are numbered sequentially: Xīngqīyī (Mon) through Xīngqīliù (Sat).")
                "Simple Questions" -> CurriculumLessonContent("谁？ 什么？ 哪里？ 什么时候？ 为什么？", "Who? What? Where? When? Why?", "Shéi? Shénme? Nǎlǐ? Shénme shíhou? Wèishénme?", "请问故宫博物院在哪里？", "Excuse me, where is the Palace Museum located?", "Questions keep natural subject-verb order; add question words in place.")
                else -> CurriculumLessonContent("吃、喝、去、来", "Eat, drink, go, come", "Chī, hē, qù, lái", "我们去茶馆喝乌龙茶吧。", "Let's go to the teahouse and drink oolong tea.", "Verbs in Chinese do not conjugate for tense, person, or number.")
            }
            3 -> when (topic) {
                "Daily Routine" -> CurriculumLessonContent("早起与晨练太极拳", "Waking up early and morning Tai Chi", "Zǎoqǐ yǔ chénliàn Tàijíquán", "我每天早晨七点起床，去公园散步。", "I wake up at seven every morning and take a walk in the park.", "Morning exercise in public parks is a vibrant social tradition.")
                "Shopping" -> CurriculumLessonContent("这个多少钱？", "How much is this?", "Zhège duōshao qián?", "老板，这件丝绸衬衫多少钱？能便宜点吗？", "Boss, how much is this silk shirt? Could it be a bit cheaper?", "Bargaining with friendly charm is widely accepted in open-air markets.")
                "Time" -> CurriculumLessonContent("现在几点钟？", "What time is it right now?", "Xiànzài jǐ diǎn zhōng?", "现在是下午两点半。", "It is 2:30 in the afternoon right now.", "'Bàn' (半) means half past the hour.")
                "Directions" -> CurriculumLessonContent("一直走，向右转", "Go straight and turn right", "Yìzhí zǒu, xiàng yòu zhuǎn", "向前一直走过两个路口，然后向左转。", "Go straight ahead past two intersections, then turn left.", "'Yòu' is right, 'zuǒ' is left.")
                "Simple Sentences" -> CurriculumLessonContent("我想预订一张高铁票", "I want to book a high-speed train ticket", "Wǒ xiǎng yùdìng", "我想买一张去杭州的高铁二等座车票。", "I want to buy a second-class ticket to Hangzhou on high-speed rail.", "Pattern: 'Wǒ xiǎng + verb' expresses desires politely.")
                else -> CurriculumLessonContent("最近怎么样？ 挺好的", "How have you been lately? Quite good", "Zuìjìn zěnmeyàng? Tǐng hǎo de", "最近工作挺顺利的，你呢？", "Work has been going quite smoothly lately, how about you?", "Warm colloquial check-in with friends and colleagues.")
            }
            4 -> when (topic) {
                "Past Events" -> CurriculumLessonContent("昨天我去参观了长城", "Yesterday I visited the Great Wall", "Zuótiān wǒ qù cānguān le Chángchéng", "不到长城非好汉，昨天的景色壮丽非凡。", "He who hasn't climbed the Great Wall is no hero; yesterday was magnificent.", "The particle 'le' (了) indicates completed action or change of state.")
                "Future Plans" -> CurriculumLessonContent("我打算下个月去西安旅游", "I plan to travel to Xi'an next month", "Wǒ dǎsuàn xià ge yuè", "明年夏天，我打算去北京大学进修汉语。", "Next summer, I plan to pursue advanced Chinese at Peking University.", "Use 'dǎsuàn' (打算) or 'yào' (要) to express future intentions.")
                "Travel" -> CurriculumLessonContent("中国高铁与高铁站", "China High-Speed Rail and station", "Zhōngguó Gāotiě", "复兴号高铁以每小时三百五十公里的速度飞驰。", "The Fuxing high-speed bullet train cruises at 350 kilometers per hour.", "China's high-speed rail network connects virtually all major cities.")
                "Restaurants" -> CurriculumLessonContent("服务员，买单！", "Server, the bill please!", "Fúwùyuán, mǎidān!", "菜品非常美味，服务员，麻烦买单。", "The dishes were delicious; server, the bill please.", "Saying 'mǎidān' is standard across all Chinese dining establishments.")
                "Describing People" -> CurriculumLessonContent("热情、幽默而且靠谱", "Warm-hearted, humorous, and dependable", "Rèqíng, yōumò érqiě kàopǔ", "我的新同事性格开朗，做事非常靠谱。", "My new colleague has an outgoing personality and is very dependable.", "'Kàopǔ' is a beloved colloquial term meaning solid and reliable.")
                else -> CurriculumLessonContent("今天阳光明媚，微风和煦", "Sunny and bright today with a gentle breeze", "Yángguāng míngmèi", "春天到了，天气渐渐暖和起来了。", "Spring has arrived; the weather is gradually warming up.", "Four-character idioms (Chengyu) like 'yángguāng míngmèi' enrich descriptions.")
            }
            5 -> when (topic) {
                "Longer Conversations" -> CurriculumLessonContent("请允许我谈谈自己的看法", "Please allow me to share my views", "Qǐng yǔnxǔ wǒ tán tan", "关于这个方案，请允许我谈谈个人的见解。", "Regarding this proposal, please allow me to share my personal insight.", "Polite participative conversational formulas.")
                "Opinions" -> CurriculumLessonContent("依我看来 / 在我看来", "In my view / As I see it", "Yī wǒ kànlái", "在我看来，绿色低碳发展是未来的必然趋势。", "In my view, green low-carbon development is an inevitable future trend.", "'Zài wǒ kànlái' introduces analytical perspectives gracefully.")
                "Experiences" -> CurriculumLessonContent("一次难忘的丝绸之路之旅", "An unforgettable Silk Road journey", "Yí cì nánwàng de Lǚxíng", "在敦煌莫高窟欣赏古代壁画，令人震撼。", "Admiring ancient murals in Dunhuang Mogao Caves was awe-inspiring.", "Reflecting on monumental cultural journeys.")
                "Comparisons" -> CurriculumLessonContent("高铁比长途汽车快得多", "High-speed rail is much faster than long-distance buses", "Gāotiě bǐ qìchē kuài de duō", "乘坐高铁比坐汽车舒适得多。", "Riding high-speed rail is far more comfortable than by car.", "Pattern: A 'bǐ' B [adjective] + 'de duō'.")
                "More Complex Grammar" -> CurriculumLessonContent("如果... 就... (假设句)", "If... then... conditional sentences", "Rúguǒ... jiù...", "如果有机会，我一定要去桂林看山水。", "If I get the chance, I will definitely go see Guilin's karst landscapes.", "Conditional pair 'rúguǒ... jiù...' links condition to outcome.")
                else -> CurriculumLessonContent("中文播客与听力提升", "Chinese podcasts and listening comprehension", "Zhōngwén bōkè", "坚持收听新闻广播，熟悉不同语速与语调。", "Consistently listen to news radio to familiarize yourself with varied speech tempos.", "Pay close attention to third-tone sandhi rules in natural speech.")
            }
            6 -> when (topic) {
                "Storytelling" -> CurriculumLessonContent("很久很久以前，在古老的中原...", "Long, long ago, in the ancient Central Plains...", "Hěn jiǔ hěn jiǔ yǐqián", "塞翁失马，焉知非福的故事道出了深刻哲理。", "The fable of the old frontiersman losing his horse conveys deep philosophical wisdom.", "Chinese fables (Yùyán) distill moral balance into everyday life.")
                "Workplace Conversations" -> CurriculumLessonContent("企业商务会议与季度目标", "Corporate business meeting and quarterly milestones", "Qǐyè shāngwù huìyì", "我们必须紧密协作，确保项目按时高质量交付。", "We must collaborate closely to ensure high-quality on-time delivery.", "Corporate Chinese in modern tech hubs is fast and results-driven.")
                "Social Situations" -> CurriculumLessonContent("有朋自远方来，不亦乐乎", "Is it not delightful to have friends visit from afar?", "Yǒu péng zì yuǎnfāng lái", "非常感谢您的热情款待，让我们宾至如归。", "Thank you so much for your warm hospitality; you made us feel right at home.", "Quoting Confucius from the Analects reflects deep cultural grace.")
                "News & Media" -> CurriculumLessonContent("人民日报与新闻评论", "People's Daily and news commentary", "Rénmín Rìbào", "主流媒体深度解读国家科技创新的重大突破。", "Mainstream media provides in-depth interpretation of major tech breakthroughs.", "Journalistic Chinese uses concise classical vocabulary (Shūmiànyǔ).")
                "Idiomatic Expressions" -> CurriculumLessonContent("千里之行，始于足下", "A journey of a thousand miles begins with a single step", "Qiānlǐ zhī xíng, shǐ yú zú xià", "只要坚持不懈，微小的努力终将成就伟大的事业。", "As long as one perseveres, tiny efforts will eventually achieve great feats.", "Famous ancient wisdom attributed to Laozi.")
                else -> CurriculumLessonContent("把字句 与 被字句", "The 'Bǎ' disposal and 'Bèi' passive constructions", "Bǎ zì jù yǔ Bèi zì jù", "他把所有的准备工作都认真做好了。", "He carried out all preparatory work with great diligence.", "'Bǎ' sentences emphasize the handling and result of an object.")
            }
            7 -> when (topic) {
                "Complex Conversations" -> CurriculumLessonContent("科技创新与社会数字化转型", "Tech innovation and digital societal transition", "Kējì chuàngxīn", "数字化转型正在深刻重塑传统产业的生产格局。", "Digital transformation is profoundly reshaping traditional industrial production.", "Discussing macro-economic issues in formal Mandarin.")
                "Debate & Opinions" -> CurriculumLessonContent("恕我不能完全赞同您的观点", "Pardon me, but I cannot fully agree with your point", "Shù wǒ bù néng zàntóng", "您提出的论点很有启发，但我认为还需考量另一因素。", "Your argument is very inspiring, but I believe another factor must be weighed.", "Diplomatic dissent delivered with consummate scholarly respect.")
                "Abstract Topics" -> CurriculumLessonContent("天人合一与中庸之道", "Harmony between humanity and nature, and the Golden Mean", "Tiān rén hé yī", "天人合一是中国古代哲学对人与自然关系的核心阐释。", "Harmony between humanity and nature is the core ancient philosophy of ecology.", "Core pillars of Daoist and Confucian intellectual thought.")
                "Natural Expressions" -> CurriculumLessonContent("画龙点睛 / 班门弄斧", "Adding the dragon's eyes / Showing off before masters", "Huà lóng diǎn jīng", "他的精辟点评为整篇报告起到了画龙点睛的作用。", "His incisive commentary brought the whole report brilliantly to life.", "Chengyu idioms communicate vast meaning in four characters.")
                "Listening Comprehension" -> CurriculumLessonContent("学术研讨会与专家讲座", "Academic symposiums and expert keynote lectures", "Xuéshù yántǎohuì", "在语速极快的学术辩论中精准捕捉核心论据。", "Accurately capturing core arguments in rapid-fire academic debates.", "Follow spoken high-register Chinese with rapid terminology.")
                else -> CurriculumLessonContent("议论文的严密逻辑与论证", "Rigorous logic and argumentation in persuasive essays", "Yìlùnwén", "确立鲜明论点，并以确凿论据进行严谨阐述。", "Establishing a clear thesis and expounding rigorously with verified evidence.", "HSK Level 6 argumentative composition standard.")
            }
            8 -> when (topic) {
                "Advanced Conversations" -> CurriculumLessonContent("前瞻性战略规划与统筹", "Foresighted strategic planning and coordination", "Qiánzhānxìng zhànlüè", "面对复杂多变的国际形势，必须保持战略定力。", "Facing complex international dynamics, we must maintain strategic composure.", "Executive leadership and policy vocabulary.")
                "Cultural Context" -> CurriculumLessonContent("唐诗宋词与中国古典文学", "Tang poetry, Song lyrics, and classical literature", "Tángshī Sòngcí", "李白、杜甫与苏轼的作品展现了汉语诗歌的巅峰艺术。", "Works of Li Bai, Du Fu, and Su Shi represent the zenith of poetic art.", "Reciting poetry adds unparalleled cultural depth to conversation.")
                "Nuanced Vocabulary" -> CurriculumLessonContent("博大精深、炉火纯青", "Broad and profound / Reaching the pinnacle of perfection", "Bódà jīngshēn", "中国传统中医药学博大精深，历久弥新。", "Traditional Chinese medicine is broad, profound, and enduringly relevant.", "High literary vocabulary.")
                "Advanced Listening" -> CurriculumLessonContent("方言口音与各地普通话特色", "Regional dialect accents in spoken Mandarin", "Fāngyán kǒuyīn", "辨识带有粤语、吴语或北方口音的普通话发音特点。", "Distinguishing Mandarin inflected with Cantonese, Shanghainese, or northern twang.", "Navigating varied regional Chinese accents with ease.")
                "Formal vs Informal Speech" -> CurriculumLessonContent("书面语与口头语的转换艺术", "The art of shifting between formal and colloquial registers", "Shūmiànyǔ yǔ Kǒutóuyǔ", "在正式公文与亲切随和的口语交流之间自如切换。", "Effortlessly switching between formal official communiqués and friendly casual speech.", "Mastering register flexibility.")
                else -> CurriculumLessonContent("文言文虚词在现代汉语中的活用", "Classical Chinese particles in modern prose", "Wényánwén xūcí", "之、乎、者、也等文言元素使现代政论文章更具典雅气韵。", "Classical particles lend elegance and rhetorical weight to modern analytical essays.", "Elevating prose with classical touches.")
            }
            9 -> when (topic) {
                "Professional Communication" -> CurriculumLessonContent("跨国战略投资与双边协议", "Multinational strategic investment and bilateral pacts", "Kuàguó zhànlüè tóuzī", "双方代表团圆满签署了全面战略伙伴关系合作备忘录。", "Both delegations signed the comprehensive strategic partnership memorandum.", "High corporate and diplomatic Mandarin.")
                "Advanced Reading" -> CurriculumLessonContent("鲁迅杂文与曹雪芹《红楼梦》", "Lu Xun's essays and Dream of the Red Chamber", "Lǔ Xùn / Hóng Lóu Mèng", "《红楼梦》被誉为中国封建社会的百科全书，艺术价值极高。", "Dream of the Red Chamber is revered as the ultimate encyclopedia of classical China.", "Reading foundational literary classics in original Chinese.")
                "Idioms & Expressions" -> CurriculumLessonContent("沧海一粟 / 卧薪尝胆", "A drop in the ocean / Enduring hardships to attain victory", "Cānghǎi yí sù", "在浩瀚的历史长河中，个人荣辱宛如沧海一粟。", "In the vast river of history, personal fortunes are like a drop in the ocean.", "Profound historical allusions.")
                "Advanced Writing" -> CurriculumLessonContent("学术专著与深度行业白皮书", "Academic monographs and in-depth industry white papers", "Báipíshū", "以详实数据与前沿理论撰写具有行业指导意义的白皮书。", "Authoring authoritative white papers with comprehensive empirical data.", "Scholarly and policy prose.")
                "Difficult Listening" -> CurriculumLessonContent("新闻发布会现场同声传译", "Live press conferences and simultaneous interpretation", "Xīnwén fābùhuì", "在瞬息万变的记者问答中准确理解言外之意与机锋。", "Accurately deciphering subtext and quick-witted parries in press Q&A sessions.", "Supreme real-time auditory comprehension.")
                else -> CurriculumLessonContent("出口成章的母语级修养", "Eloquence flowing like written prose (native polish)", "Chūkǒu chéng zhāng", "无论是即兴演讲还是学术辩驳，皆能引经据典、游刃有余。", "Whether in impromptu speeches or academic debate, quoting classics effortlessly.", "Complete bilingual mastery.")
            }
            else -> when (topic) {
                "Natural Conversation" -> CurriculumLessonContent("行云流水般的纯正表达", "Pure, flowing expression like moving clouds and water", "Xíng yún liú shuǐ", "谈吐风雅、语调自如，达到人语合一的崇高境界。", "Speaking with natural elegance and ease, achieving complete oneness with the language.", "Native cadence without a trace of hesitation.")
                "Humor & Cultural References" -> CurriculumLessonContent("相声的包袱与曲艺幽默", "Xiangsheng cross-talk punchlines and folk humor", "Xiàngsheng bāofu", "领略中国相声艺术的铺垫与抖包袱，体味深层次文化幽默。", "Appreciating the setup and punchlines of Chinese cross-talk humor.", "Appreciating sophisticated cultural wit.")
                "Advanced Debates" -> CurriculumLessonContent("雄辩之才与大家风范", "Commanding rhetorical brilliance and masterly presence", "Xióngbiàn zhī cái", "以缜密的逻辑与磅礴的气势征服全场，展现大师风采。", "Conquering the audience with rigorous logic and majestic presence.", "Mastery over public oration.")
                "Professional Fluency" -> CurriculumLessonContent("国际多边论坛的领袖风范", "Leadership across international multilateral forums", "Lǐngxiù fēngfàn", "在博鳌亚洲论坛等全球顶级舞台上以流利中文指点江山。", "Leading keynote deliberations at premier global summits in fluent Chinese.", "Supreme executive leadership.")
                "Native-Speed Listening" -> CurriculumLessonContent("秋毫皆察的听觉直觉", "Acute auditory intuition perceiving the finest hair", "Qiūháo jiē chá", "在众人快速交锋的复杂语境下，对每一处隐喻心领神会。", "Grasping every metaphor and subtle nuance even in complex rapid exchanges.", "Total acoustic mastery.")
                else -> CurriculumLessonContent("融会贯通的中华文化通达", "Comprehensive cultural and linguistic integration", "Rónghuì guàntōng", "深刻体悟华夏文明精髓，真正做到融汇中西、博古通今。", "Comprehending the essence of Chinese civilization, bridging East and West effortlessly.", "Total cultural and linguistic harmony.")
            }
        }
    }
}
